&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Participation in &lt;span data-contrast=&quot;auto&quot;&gt;trading competitions&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;math contests&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;competitive gaming&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, or &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;poker&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;.&lt;/span&gt; &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;4&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif; font-size: 12pt;&quot;&gt;Familiarity with &lt;span data-contrast=&quot;auto&quot;&gt;machine learning&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; techniques such as regression, neural networks, or SVMs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
